package soloid

import (
	"bytes"
	"encoding/base64"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"
)

func TestPreviousImplementationSession(t *testing.T) {
	// session.jwt was generated by the previous Node jose SignJWT/HKDF/HMAC code.
	// It uses public test credentials and a fixed 2023 clock, never production keys.
	c := configCopy(t, fixture(t))
	c.Secret = base64.RawURLEncoding.EncodeToString(bytes.Repeat([]byte{7}, 32))
	c.Users[0].PasswordHash = "$argon2id$v=19$m=65536,t=3,p=4$BwcHBwcHBwcHBwcHBwcHBw$PuPCRNNjHmNdNNI7G8xwshS44z9xhv0+wpdVNmc99yw"
	p := NewProvider(prepared(t, c), nil)
	now := time.Unix(1700000100, 0)
	p.now = func() time.Time { return now }
	b := newBrowser(t, p)
	token, err := os.ReadFile("testdata/session.jwt")
	if err != nil {
		t.Fatal(err)
	}
	b.cookies["soloid-session"] = &http.Cookie{Name: "soloid-session", Value: strings.TrimSpace(string(token))}
	a := authParams("public")
	a.Set("prompt", "none")
	if location(t, b.start(a)).Get("code") == "" {
		t.Fatal("previous session was not preserved")
	}
	now = time.Unix(1700043200, 0)
	if location(t, b.start(a)).Get("error") != "login_required" {
		t.Fatal("previous session did not expire")
	}
}
